-- Projects generated by the builder
CREATE TABLE public.projects (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  title text NOT NULL,
  dream text NOT NULL,
  summary text,
  stack text[] NOT NULL DEFAULT '{}',
  sprints jsonb NOT NULL DEFAULT '[]'::jsonb,
  files jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX projects_user_idx ON public.projects (user_id, created_at DESC);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.projects TO authenticated;
GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own projects select" ON public.projects FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "own projects insert" ON public.projects FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own projects update" ON public.projects FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own projects delete" ON public.projects FOR DELETE TO authenticated USING (auth.uid() = user_id);

-- Research / literature / report artifacts (Module 4)
CREATE TABLE public.research_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('papers','review','report')),
  topic text NOT NULL,
  content text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX research_user_idx ON public.research_items (user_id, created_at DESC);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.research_items TO authenticated;
GRANT ALL ON public.research_items TO service_role;
ALTER TABLE public.research_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own research select" ON public.research_items FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "own research insert" ON public.research_items FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own research delete" ON public.research_items FOR DELETE TO authenticated USING (auth.uid() = user_id);

-- Code scans (Project Studio)
CREATE TABLE public.code_scans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  filename text NOT NULL,
  language text,
  code text NOT NULL,
  summary text,
  findings jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX code_scans_user_idx ON public.code_scans (user_id, created_at DESC);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.code_scans TO authenticated;
GRANT ALL ON public.code_scans TO service_role;
ALTER TABLE public.code_scans ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own scans select" ON public.code_scans FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "own scans insert" ON public.code_scans FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own scans delete" ON public.code_scans FOR DELETE TO authenticated USING (auth.uid() = user_id);

-- Token ledger
CREATE TABLE public.token_ledger (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  delta integer NOT NULL,
  reason text NOT NULL,
  balance_after integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX token_ledger_user_idx ON public.token_ledger (user_id, created_at DESC);
GRANT SELECT ON public.token_ledger TO authenticated;
GRANT ALL ON public.token_ledger TO service_role;
ALTER TABLE public.token_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own ledger select" ON public.token_ledger FOR SELECT TO authenticated USING (auth.uid() = user_id);

-- Spend tokens atomically; returns new balance, or -1 when not enough tokens
CREATE OR REPLACE FUNCTION public.spend_tokens(_amount integer, _reason text)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _uid uuid := auth.uid();
  _new integer;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF _amount IS NULL OR _amount < 1 THEN
    RAISE EXCEPTION 'invalid amount';
  END IF;

  UPDATE public.profiles
     SET tokens = tokens - _amount
   WHERE id = _uid AND tokens >= _amount
  RETURNING tokens INTO _new;

  IF _new IS NULL THEN
    RETURN -1;
  END IF;

  INSERT INTO public.token_ledger (user_id, delta, reason, balance_after)
  VALUES (_uid, -_amount, _reason, _new);

  RETURN _new;
END;
$$;
GRANT EXECUTE ON FUNCTION public.spend_tokens(integer, text) TO authenticated;